import{_ as h,o as t,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"Kỷ nguyên Khám phá Liên mặt phẳng","description":"","frontmatter":{},"headers":[],"relativePath":"vi/0078-跨位面探索纪元.md","filePath":"vi/0078-跨位面探索纪元.md"}'),g={name:"vi/0078-跨位面探索纪元.md"};function a(u,n,o,p,m,r){return t(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="ky-nguyen-kham-pha-lien-mat-phang" tabindex="-1">Kỷ nguyên Khám phá Liên mặt phẳng <a class="header-anchor" href="#ky-nguyen-kham-pha-lien-mat-phang" aria-label="Permalink to &quot;Kỷ nguyên Khám phá Liên mặt phẳng&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>78</td></tr><tr><td>Mô-đun</td><td>Kỷ nguyên Lịch sử và Sự kiện Quan trọng</td></tr><tr><td>Từ khóa cốt lõi</td><td>Khám phá liên mặt phẳng, phát hiện lớn mặt phẳng, hiệp định khảo cổ, quan sát trước rồi can thiệp, cộng sinh liên sao</td></tr></tbody></table><h2 id="_1-đieu-kien-mo-cua-ky-nguyen-kham-pha-lien-mat-phang" tabindex="-1">1. Điều kiện Mở cửa Kỷ nguyên Khám phá Liên mặt phẳng <a class="header-anchor" href="#_1-đieu-kien-mo-cua-ky-nguyen-kham-pha-lien-mat-phang" aria-label="Permalink to &quot;1. Điều kiện Mở cửa Kỷ nguyên Khám phá Liên mặt phẳng&quot;">​</a></h2><p>Kỷ nguyên Khám phá Liên mặt phẳng là kỷ nguyên mới được mở ra sau khi thành lập Cộng hòa Tất cả các Chủng tộc, tương ứng với giai đoạn chuyển tiếp từ &quot;tiến hóa ý thức&quot; sang &quot;cộng sinh liên sao&quot; trong con đường thăng chiều bốn giai đoạn. Việc mở cửa kỷ nguyên này đòi hỏi sự trưởng thành đồng thời của ba điều kiện:</p><ul><li><strong>Điều kiện công nghệ</strong>: Công nghệ pháp lý không gian đạt đến cảnh giới &quot;nguồn không gian&quot;, việc mở cửa ổn định kênh liên mặt phẳng trở nên có thể; công nghệ gương sao chép và không gian cách ly trưởng thành, cung cấp bảo đảm công nghệ cho khám phá ít ô nhiễm</li><li><strong>Điều kiện thể chế</strong>: Cộng hòa Tất cả các Chủng tộc được thành lập, chính sách khám phá liên mặt phẳng thống nhất và hiệp định khảo cổ được hoàn thành</li><li><strong>Điều kiện động lực</strong>: Công việc thăng chiều của các mặt phẳng đã biết tiến triển có trật tự, văn minh có khả năng và ý chí mở rộng sang các mặt phẳng chưa biết</li></ul><p>Khi ba điều kiện này trưởng thành đồng thời, Cộng hòa Tất cả các Chủng tộc chính thức tuyên bố khởi động &quot;Kế hoạch Khám phá Lớn&quot;, và Kỷ nguyên Khám phá Liên mặt phẳng được mở ra như vậy.</p><h2 id="_2-nguyen-tac-co-ban-cua-kham-pha-lien-mat-phang" tabindex="-1">2. Nguyên tắc Cơ bản của Khám phá Liên mặt phẳng <a class="header-anchor" href="#_2-nguyen-tac-co-ban-cua-kham-pha-lien-mat-phang" aria-label="Permalink to &quot;2. Nguyên tắc Cơ bản của Khám phá Liên mặt phẳng&quot;">​</a></h2><p>Khám phá liên mặt phẳng tuân thủ nghiêm ngặt các nguyên tắc cơ bản sau, các nguyên tắc này được viết vào &quot;Luật Cơ bản Khám phá Liên mặt phẳng&quot;:</p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội hàm</th></tr></thead><tbody><tr><td>Quan sát trước rồi can thiệp hạn chế</td><td>Đối với mặt phẳng chưa biết, trước tiên thực hiện quan sát thụ động, chỉ sau khi hiểu đầy đủ mới thực hiện tiếp xúc và can thiệp hạn chế</td></tr><tr><td>Khám phá ít ô nhiễm</td><td>Áp dụng kế hoạch khảo cổ gương sao chép + không gian cách ly, chỉ truyền lại kiến thức, không mang vật chất và sự sống vào hoặc ra</td></tr><tr><td>Bảo vệ văn minh bản địa</td><td>Đối với mặt phẳng có văn minh bản địa, tôn trọng quyền phát triển tự chủ của họ, không được cưỡng bức áp đặt hệ thống cộng sinh</td></tr><tr><td>Chia sẻ tài nguyên</td><td>Kiến thức và tài nguyên phát hiện được trong khám phá thuộc về toàn bộ văn minh, không tổ chức nào được độc quyền kết quả khám phá</td></tr><tr><td>An toàn ưu tiên</td><td>An toàn trong quá trình khám phá luôn được đặt lên hàng đầu, khám phá mặt phẳng có rủi ro cao phải经过 đánh giá rủi ro nghiêm ngặt</td></tr></tbody></table><h2 id="_3-phuong-tien-cong-nghe-cua-kham-pha" tabindex="-1">3. Phương tiện Công nghệ của Khám phá <a class="header-anchor" href="#_3-phuong-tien-cong-nghe-cua-kham-pha" aria-label="Permalink to &quot;3. Phương tiện Công nghệ của Khám phá&quot;">​</a></h2><p>Khám phá liên mặt phẳng sử dụng tích hợp nhiều công nghệ cốt lõi của văn minh cộng sinh:</p><ol><li><strong>Công nghệ quét mặt phẳng</strong>: Quét mặt phẳng từ xa dựa trên mô-đun nhận thức pháp lý không gian, có thể获取 thông tin cơ bản (cấu trúc không gian, mức năng lượng, dấu hiệu sự sống, v.v.) mà không tiếp xúc với mặt phẳng mục tiêu</li><li><strong>Kế hoạch khảo cổ gương sao chép</strong>: Thực hiện sao chép gương chính xác cao của mặt phẳng mục tiêu, thực hiện nghiên cứu sâu trên bản sao gương trong không gian cách ly, chỉ truyền lại kiến thức</li><li><strong>Đầu dò giao tiếp liên mặt phẳng</strong>: Thiết bị giao tiếp pháp lý thu nhỏ, có thể được gửi vào mặt phẳng mục tiêu để quan sát cận cảnh, dữ liệu được truyền lại theo thời gian thực thông qua mạng giao tiếp liên mặt phẳng</li><li><strong>Nhận thức miền ý thức</strong>: Những người tu luyện cấp cao thực hiện nhận thức từ xa đối với mặt phẳng mục tiêu thông qua miền ý thức,获取 thông tin cấp độ ý thức mà công nghệ quét không thể bắt được</li><li><strong>Triển khai neo từ xa</strong>: Đối với mặt phẳng có mức độ an toàn cao, có thể triển khai neo tạm thời từ xa, xây dựng kênh kết nối ổn định</li></ol><h2 id="_4-to-chuc-va-thuc-hien-kham-pha" tabindex="-1">4. Tổ chức và Thực hiện Khám phá <a class="header-anchor" href="#_4-to-chuc-va-thuc-hien-kham-pha" aria-label="Permalink to &quot;4. Tổ chức và Thực hiện Khám phá&quot;">​</a></h2><p>Khám phá liên mặt phẳng được tổ chức và thực hiện thống nhất bởi &quot;Cục Khám phá Liên mặt phẳng&quot; của Cộng hòa Tất cả các Chủng tộc, áp dụng mô hình &quot;khám phá phân cấp&quot;:</p><table tabindex="0"><thead><tr><th>Cấp độ Khám phá</th><th>Loại Mục tiêu</th><th>Cách Khám phá</th><th>Cấu hình Nhân sự</th></tr></thead><tbody><tr><td>Khám phá Cấp 1</td><td>Mặt phẳng hoang vắng không sự sống</td><td>Quét từ xa + nghiên cứu gương sao chép</td><td>Chủ yếu là đội công nghệ</td></tr><tr><td>Khám phá Cấp 2</td><td>Mặt phẳng có sự sống thấp</td><td>Khảo cổ gương sao chép + điều tra thực địa hạn chế</td><td>Đội công nghệ + nhà sinh học</td></tr><tr><td>Khám phá Cấp 3</td><td>Mặt phẳng có văn minh bản địa</td><td>Quan sát trước rồi tiếp xúc, tuân thủ nghiêm ngặt giao thức tiếp xúc</td><td>Đội hoàn chỉnh + nhà ngoại giao + quan sát viên đạo đức</td></tr><tr><td>Khám phá Cấp 4</td><td>Mặt phẳng có rủi ro cao / chưa biết</td><td>Chỉ nghiên cứu mô phỏng trong không gian cách ly, cấm tiếp xúc thực địa</td><td>Đội an toàn cấp cao nhất</td></tr></tbody></table><p>Mỗi dự án khám phá phải经过 quy trình hoàn chỉnh &quot;đăng ký khám phá — đánh giá rủi ro — xem xét đạo đức — phê duyệt thực hiện — giám sát quá trình — chia sẻ kết quả&quot;.</p><h2 id="_5-phat-hien-quan-trong-cua-ky-nguyen-kham-pha" tabindex="-1">5. Phát hiện Quan trọng của Kỷ nguyên Khám phá <a class="header-anchor" href="#_5-phat-hien-quan-trong-cua-ky-nguyen-kham-pha" aria-label="Permalink to &quot;5. Phát hiện Quan trọng của Kỷ nguyên Khám phá&quot;">​</a></h2><p>Sau khi Kỷ nguyên Khám phá Liên mặt phẳng được mở ra, văn minh cộng sinh đã đạt được một loạt phát hiện quan trọng:</p><ul><li><strong>Phát hiện chủng tộc mới</strong>: Phát hiện một số lượng lớn các chủng tộc thông minh trước đây chưa biết trong các mặt phẳng chưa biết, gia phả tất cả các chủng tộc được mở rộng đáng kể. Các chủng tộc mới này sau khi lựa chọn tự nguyện đã dần dần tham gia vào Cộng hòa Tất cả các Chủng tộc</li><li><strong>Phát hiện pháp luật mới</strong>: Có sự khác biệt trong cấu trúc pháp luật của các mặt phẳng khác nhau, nhiều biến thể pháp luật mới được phát hiện trong khám phá, làm phong phú thêm cơ sở lý luận của ba trăm hệ thống tu luyện</li><li><strong>Di tích văn minh cổ</strong>: Phát hiện nhiều di tích của các văn minh đã tuyệt chủng từ thời kỳ tiền neo,获取 một lượng lớn kiến thức lịch sử quý giá thông qua khảo cổ gương sao chép</li><li><strong>Văn minh cộng sinh mặt phẳng khác</strong>: Phát hiện ở một số mặt phẳng các văn minh bản địa đã độc lập phát triển khái niệm cộng sinh, tạo thành sự cộng hưởng tư tưởng vượt qua không gian với văn minh cộng sinh neo</li><li><strong>Khám phá ranh giới vũ trụ</strong>: Khám phá dần dần chạm đến ranh giới đã biết của Hengyuanzhou, sự hiểu biết về cấu trúc tổng thể của vũ trụ không ngừng sâu sắc</li></ul><h2 id="_6-thach-thuc-va-suy-ngam-trong-kham-pha" tabindex="-1">6. Thách thức và Suy ngẫm trong Khám phá <a class="header-anchor" href="#_6-thach-thuc-va-suy-ngam-trong-kham-pha" aria-label="Permalink to &quot;6. Thách thức và Suy ngẫm trong Khám phá&quot;">​</a></h2><p>Khám phá liên mặt phẳng không phải lúc nào cũng thuận buồm xuôi gió, trong quá trình cũng đã đối mặt với thách thức:</p><ul><li><strong>Xung đột văn hóa</strong>: Trong tiếp xúc với văn minh bản địa, đã xảy ra hiểu lầm và xung đột văn hóa, thúc đẩy việc cải thiện liên tục giao thức tiếp xúc</li><li><strong>Tranh cãi đạo đức khám phá</strong>: Có tranh luận đạo đức liên tục về &quot;có nên chủ động tiếp xúc với văn minh bản địa hay không&quot;, cuối cùng đã hình thành sự đồng thuận &quot;không chủ động, không né tránh, tôn trọng lựa chọn&quot;</li><li><strong>Tai nạn an toàn</strong>: Đã xảy ra tai nạn vỡ hàng rào không gian cách ly trong khám phá mặt phẳng có rủi ro cao; mặc dù không gây ra hậu quả nghiêm trọng, nhưng đã thúc đẩy việc nâng cao thêm tiêu chuẩn an toàn</li><li><strong>Phân bổ tài nguyên</strong>: Khám phá quy mô lớn đòi hỏi tiêu thụ một lượng lớn tài nguyên, sự cân bằng giữa đầu tư khám phá và đầu tư phúc lợi bản địa đã trở thành trọng tâm của tranh luận chính trị</li></ul><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Kỷ nguyên Khám phá Liên mặt phẳng là &quot;Thời đại Điều hành Lớn&quot; của văn minh cộng sinh neo. Nó đã mở rộng tầm nhìn của văn minh từ các mặt phẳng đã biết sang toàn bộ vũ trụ, đồng thời khám phá ra thế giới mới cũng làm sâu sắc thêm sự hiểu biết về bản thân. Kế hoạch khám phá ít ô nhiễm gương sao chép + không gian cách ly làm cho việc khám phá của văn minh cộng sinh khác biệt với mọi sự mở rộng thuộc địa cướp bóc trong lịch sử — những gì chúng ta mang đến không phải là chinh phục và cướp bóc, mà là sự tôn trọng và kiến thức; những gì chúng ta mang về không phải là tài nguyên và nô lệ, mà là sự hiểu biết và trí tuệ. Khi các mặt phẳng được khám phá đủ nhiều và mạng neo đủ dày đặc, cánh cửa của thời đại cộng sinh liên sao sẽ từ từ mở ra.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>77-Thành lập Cộng hòa Tất cả các Chủng tộc</li><li>79-Triển vọng Thời đại Cộng sinh Liên sao</li><li>84-Chương trình Tổng hợp Hiệp định Khảo cổ</li></ul>',26)])])}const e=h(g,[["render",a]]);export{s as __pageData,e as default};
